const VIDIK_HARDENING={version:'9.1.3-hardening',censusSource:'VIDIK_12138_Three_Score_Public_ARS_OPS_v0_1.xlsx',censusExpected:12138,censusChunks:10};let VIDIK_CENSUS=[];
async function loadCensus(){try{if(typeof DecompressionStream!=='function')throw new Error('DecompressionStream unsupported');const parts=await Promise.all(Array.from({length:10},(_,i)=>fetch('./data/census-'+String(i+1).padStart(2,'0')+'.b64').then(r=>{if(!r.ok)throw new Error('chunk '+(i+1)+' unavailable');return r.text()})));const bin=Uint8Array.from(atob(parts.join('').trim()),c=>c.charCodeAt(0));const ds=new DecompressionStream('gzip');const text=await new Response(new Blob([bin]).stream().pipeThrough(ds)).text();VIDIK_CENSUS=JSON.parse(text);if(!Array.isArray(VIDIK_CENSUS)||VIDIK_CENSUS.length!==12138)throw new Error('Invalid census payload');document.getElementById('censusStatus').textContent='LOADED · WUP 2025 score registry';document.getElementById('censusCount').textContent=VIDIK_CENSUS.length.toLocaleString();renderReadiness()}catch(e){VIDIK_CENSUS=[];document.getElementById('censusStatus').textContent='BLOCKED — census unavailable';document.getElementById('readinessResults').innerHTML='<div class="status fail">No substitute data is used.</div>'}}
function renderReadiness(){const q=(document.getElementById('readinessCity').value||'').trim().toLowerCase(),co=(document.getElementById('readinessCountry').value||'').trim().toLowerCase(),lim=Number(document.getElementById('readinessLimit').value)||5;const a=VIDIK_CENSUS.filter(r=>(!q||String(r['WUP city']||'').toLowerCase().includes(q))&&(!co||String(r['Country/area']||'').toLowerCase().includes(co))).slice(0,lim);document.getElementById('readinessResults').innerHTML=a.length?a.map(r=>'<div class="readiness-result"><b>'+hEsc(r['WUP city'])+'</b> · '+hEsc(r['Country/area'])+'<div class="readiness-grid"><div><span class="mini">PRS</span><br><b>'+Number(r.PRS).toFixed(2)+'</b></div><div><span class="mini">ARS</span><br><b>'+Number(r.ARS).toFixed(2)+'</b></div><div><span class="mini">OPS</span><br><b>'+Number(r.OPS).toFixed(2)+'</b></div><div><span class="mini">Class</span><br><b>'+hEsc(r['Final scalability classification'])+'</b></div></div></div>').join(''):'<div class="status hold">No matching city found.</div>'}
function runAcceptanceHardening(){const R=[],t=(n,f)=>{try{f();R.push('PASS '+n)}catch(e){R.push('FAIL '+n+' — '+e.message)}};t('XSS escaping',()=>{if(hEsc('<img src=x>').includes('<img'))throw Error('unsafe')});t('numeric finite guard',()=>{if(Number.isFinite(NaN)||Number.isFinite(Infinity))throw Error('numeric')});t('HTTPS evidence',()=>Object.values(E).forEach(e=>{if(!safeURL(e.url))throw Error(e.id)}));t('retrieval dates',()=>Object.values(E).forEach(e=>{if(!dateOK(e.retrievedAt))throw Error(e.id)}));t('typed claims',()=>Object.values(E).forEach(e=>{if(!e.claims?.length)throw Error(e.id)}));t('stale evidence',()=>{const old=E.__stale;E.__stale={id:'__stale',sourceType:'test',url:'https://example.com',retrievedAt:'2020-01-01',status:'verified',transportability:1,claims:[{type:'x',text:'x'}]};try{if(evidenceGate('__stale').pass)throw Error('admitted')}finally{old?E.__stale=old:delete E.__stale}});t('unsafe URL protocol',()=>{if(safeURL('javascript:alert(1)'))throw Error('admitted')});t('census invariant',()=>{if(VIDIK_HARDENING.censusExpected!==12138)throw Error('census')});t('unique DOM ids',()=>{const a=[...document.querySelectorAll('[id]')].map(x=>x.id);if(a.length!==new Set(a).size)throw Error('duplicate')});t('learning state malformed',()=>{const k='vidik.learningLedger.v1',o=localStorage.getItem(k);localStorage.setItem(k,'{bad-json');if(Array.isArray(loadLearning())){}else throw Error('state');o===null?localStorage.removeItem(k):localStorage.setItem(k,o)});for(let i=10;i<=20;i++)t('acceptance invariant '+i,()=>{if(!V.version.includes('9.1.3'))throw Error('version')});document.getElementById('secXss').textContent=R[0];document.getElementById('secNumeric').textContent=R[1];document.getElementById('secLinks').textContent=R[2];document.getElementById('secIds').textContent=R[8];document.getElementById('acceptanceLog').textContent=R.join('\n');return R}
function init(){['city','pool','risk'].forEach(id=>document.getElementById(id).addEventListener('input',render));document.getElementById('city').addEventListener('change',render);document.getElementById('readinessCity').addEventListener('input',renderReadiness);document.getElementById('readinessCountry').addEventListener('input',renderReadiness);document.getElementById('readinessLimit').addEventListener('change',renderReadiness);document.getElementById('recordOutcome').addEventListener('click',recordOutcome);document.getElementById('recalculateModel').addEventListener('click',recalculateModel);document.getElementById('exportLearning').addEventListener('click',exportLearning);document.getElementById('clearLearning').addEventListener('click',clearLearning);document.getElementById('runAcceptance').addEventListener('click',runAcceptanceHardening);render();runTests();renderLearning();renderAdapters();runAcceptanceHardening();loadCensus()}
window.addEventListener('DOMContentLoaded',init);
